   675→// shellCompletionTarget returns the rc file path and completion lines for the
   676→// user's current shell. Returns empty strings for unsupported shells.
   677→func shellCompletionTarget() (rcFile, completionLine string) {
   678→	home, err := os.UserHomeDir()
   679→	if err != nil {
   680→		return "", ""
   681→	}
   682→
   683→	shell := os.Getenv("SHELL")
   684→	switch {
   685→	case strings.Contains(shell, "zsh"):
   686→		return filepath.Join(home, ".zshrc"),
   687→			"autoload -Uz compinit && compinit && source <(entire completion zsh)"
   688→	case strings.Contains(shell, "bash"):
   689→		return filepath.Join(home, ".bashrc"),
   690→			"source <(entire completion bash)"
   691→	default:
   692→		return "", ""
   693→	}
   694→}
