   696→// promptShellCompletion offers to add shell completion to the user's rc file.
   697→// Only prompts if completion is not already configured.
   698→func promptShellCompletion(w io.Writer) error {
   699→	rcFile, completionLine := shellCompletionTarget()
   700→	if rcFile == "" {
   701→		return nil // Unsupported shell or no home dir, skip silently
   702→	}
   703→
   704→	if isCompletionConfigured(rcFile, completionLine) {
   705→		return nil
   706→	}
   707→
   708→	var selected string
   709→	form := NewAccessibleForm(
   710→		huh.NewGroup(
   711→			huh.NewSelect[string]().
   712→				Title("Enable shell completion?").
   713→				Options(
   714→					huh.NewOption("Yes", "yes"),
   715→					huh.NewOption("No", "no"),
   716→				).
   717→				Value(&selected),
   718→		),
   719→	)
   720→
   721→	if err := form.Run(); err != nil {
   722→		//nolint:nilerr // User cancelled - not a fatal error, just skip
   723→		return nil
   724→	}
   725→
   726→	if selected != "yes" {
   727→		return nil
   728→	}
   729→
   730→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
   731→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
   732→	}
   733→
   734→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
   735→	fmt.Fprintln(w, "  Run `source "+rcFile+"` or restart your shell to activate")
   736→
   737→	return nil
   738→}
