   740→// isCompletionConfigured checks if shell completion is already in the rc file.
   741→func isCompletionConfigured(rcFile string, completionLine string) bool {
   742→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
   743→	content, err := os.ReadFile(rcFile)
   744→	if err != nil {
   745→		return false // File doesn't exist or can't read, treat as not configured
   746→	}
   747→	return strings.Contains(string(content), completionLine)
   748→}
   749→
   750→// appendShellCompletion adds the completion line to the rc file.
   751→func appendShellCompletion(rcFile, completionLine string) error {
   752→	//nolint:gosec // G302: Shell rc files need 0644 for user readability
   753→	f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
   754→	if err != nil {
   755→		return fmt.Errorf("opening file: %w", err)
   756→	}
   757→	defer f.Close()
   758→
   759→	_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
   760→	if err != nil {
   761→		return fmt.Errorf("writing completion: %w", err)
   762→	}
   763→	return nil
   764→}
