+			if i+1 < len(lines) && strings.TrimSpace(lines[i+1]) == completionLine {
+				i++ // skip next line too
+			}
+			removed = true
+			continue
+		}
+		result = append(result, lines[i])
+	}
+	if !removed {
+		return content, false
+	}
